using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class BRInspect {
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 edit mode required");string h=Root+"/SourceAssets/B2_SurfaceRefinement/";Directory.CreateDirectory(h);string backup="C:/Users/503-26/Documents/Codex/Backups/AfterSeconds_B2_Surface_20261110";Directory.CreateDirectory(backup);if(!File.Exists(backup+"/Level_B2_Circular.before.unity"))File.Copy(s.path,backup+"/Level_B2_Circular.before.unity");var ts=s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")).SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();string PathOf(Transform t)=>t.parent?PathOf(t.parent)+"/"+t.name:t.name;var data=ts.Select(t=>new{t.name,path=PathOf(t),active=t.gameObject.activeInHierarchy,local=new[]{t.localPosition.x,t.localPosition.y,t.localPosition.z},position=new[]{t.position.x,t.position.y,t.position.z},scale=new[]{t.lossyScale.x,t.lossyScale.y,t.lossyScale.z},yaw=t.eulerAngles.y,mesh=t.GetComponent<MeshFilter>()?AssetDatabase.GetAssetPath(t.GetComponent<MeshFilter>().sharedMesh):null,materials=t.GetComponent<Renderer>()?t.GetComponent<Renderer>().sharedMaterials.Select(m=>new{name=m?m.name:null,path=AssetDatabase.GetAssetPath(m),tex=m&&m.mainTexture?AssetDatabase.GetAssetPath(m.mainTexture):null}).ToArray():null,bounds=t.GetComponent<Renderer>()?new{center=new[]{t.GetComponent<Renderer>().bounds.center.x,t.GetComponent<Renderer>().bounds.center.y,t.GetComponent<Renderer>().bounds.center.z},size=new[]{t.GetComponent<Renderer>().bounds.size.x,t.GetComponent<Renderer>().bounds.size.y,t.GetComponent<Renderer>().bounds.size.z}}:null});File.WriteAllText(h+"before.json",JsonConvert.SerializeObject(data,Formatting.Indented));return new{transforms=ts.Length,saved=!s.isDirty,selected=Selection.activeGameObject?Selection.activeGameObject.name:null};}
